from typing import ClassVar, TypedDict

from appworld.common.utils import dump_yaml
from generate.data.static import PregeneratedItems, StaticData


class ShoppingProduct(StaticData):
    items_title: ClassVar[str | None] = "Shopping Products"
    item_separator: ClassVar[str | None] = "\n\n"
    product_type: str
    products: list[
        TypedDict(
            "Product",
            {
                "seller_name": str,
                "name": str,
                "relative_sizes": list[str],
                "colors": list[str],
                "description": str,
                "weight": float,
                "length": float,
                "width": float,
                "height": float,
                "price": float,
                "reviews": list[
                    TypedDict(
                        "Review",
                        {
                            "rating": int,
                            "title": str,
                            "text": str,
                        },
                    )
                ],
                "faqs": list[
                    TypedDict(
                        "QuestionAnswer",
                        {
                            "question": str,
                            "answers": list[str],
                        },
                    )
                ],
            },
        )
    ]

    def to_string(self) -> str:
        return dump_yaml(self.dict()).strip()

